[
  {
    "incident": {
      "component": "api-node-07:/var",
      "category": "Disk Space Exhaustion",
      "status": "firing",
      "summary": "The /var filesystem on api-node-07 is filling up rapidly at 2GiB/h, with only 20GiB remaining."
    },
    "assessment": {
      "urgency": "critical",
      "rationale": "At the current growth rate of 2GiB/h, the disk will be completely full in approximately 10 hours, which will likely cause service failure for the payments-api."
    },
    "facts": [
      "Alert: NodeFilesystemAlmostOutOfSpace",
      "Instance: api-node-07:9100",
      "Mountpoint: /var",
      "Available space: 20GiB of 250GiB",
      "Growth rate: 2GiB/h",
      "Context: Release 4.12 of payments-api was deployed 3 hours ago"
    ],
    "missing_context": [
      {
        "item": "Top disk consumers in /var",
        "why": "To identify if the growth is due to logs, temporary files, or application data",
        "how_to_check": "ssh api-node-07 'du -sh /var/* | sort -h'"
      },
      {
        "item": "Log file growth rate",
        "why": "To confirm if the new release is generating excessive logs",
        "how_to_check": "ls -lh /var/log"
      }
    ],
    "immediate_actions": [
      {
        "action": "Identify large files/directories in /var",
        "purpose": "Pinpoint the source of disk consumption",
        "conditions": "Immediately",
        "expected_effect": "Identification of the culprit (e.g., /var/log or /var/lib/docker)",
        "risks": "None",
        "requires_approval": false,
        "verify": "Output of du command",
        "rule_ids": [
          "DISK_USAGE_INVESTIGATION"
        ]
      },
      {
        "action": "Clear old rotated logs if applicable",
        "purpose": "Regain immediate disk space",
        "conditions": "If /var/log is the primary consumer and old logs are present",
        "expected_effect": "Increased available disk space",
        "risks": "Loss of historical log data for debugging",
        "requires_approval": true,
        "verify": "df -h /var",
        "rule_ids": [
          "LOG_CLEANUP"
        ]
      }
    ],
    "investigation_steps": [
      {
        "step": "Check application logs for error loops",
        "hypothesis": "Release 4.12 introduced a bug causing excessive logging",
        "how_to_check": "tail -f /var/log/payments-api.log"
      },
      {
        "step": "Check container runtime storage",
        "hypothesis": "Docker/Containerd logs or overlay2 layers are consuming space",
        "how_to_check": "docker system df"
      }
    ],
    "root_cause_hypotheses": [
      "Release 4.12 introduced verbose logging or an error loop",
      "Release 4.12 is generating large temporary files in /var",
      "Unbounded log rotation in the new deployment"
    ],
    "dangerous_operations": [
      {
        "operation": "rm -rf /var/*",
        "why_dangerous": "Could delete critical system files, databases, or container runtimes",
        "rule_id": "DESTRUCTIVE_DELETE"
      }
    ],
    "applied_expert_rules": [
      "DISK_USAGE_INVESTIGATION",
      "LOG_CLEANUP"
    ],
    "incident_update": "🚨 *Critical Alert*: /var on `api-node-07` is filling at 2GiB/h (20GiB left). This follows the 4.12 release. Investigating if logs are the cause. ETA for disk exhaustion: ~10 hours."
  }
]
